"""Complete 40 original critical-care emergency and organ-support questions."""
from create_critical_liver_ecmo_abdomen import rows,q,AK,ST,CE,SE,LF,VV,VA,ref
from qbank_authoring import finalize
NU=ref('ESPEN ICU nutrition practical guideline: 2023','https://doi.org/10.1016/j.clnu.2023.07.011')
SU=ref('SCCM/ASHP stress-related GI bleeding prevention guideline: 2024','https://sccm.org/clinical-resources/guidelines/guidelines/sccm-ashp-guideline-prevention-of-ugib')
PA=ref('SCCM focused PADIS guideline: 2025','https://www.sccm.org/clinical-resources/guidelines/guidelines/focused-update-padis-guideline')

q('A ventilated patient has completed initial resuscitation, has stable or decreasing vasopressor needs and a functioning gastrointestinal tract. Which nutrition principle is appropriate?', 'Consider early low-dose enteral nutrition and advance according to tolerance and clinical stability',[
 ('Keep every patient fasting until extubation','This unnecessarily delays nutrition in many suitable patients.'),('Provide full target calories immediately during uncontrolled escalating shock','This can be unsafe and is not the intended approach.'),('Use parenteral nutrition automatically for every intubated patient','Route selection depends on gastrointestinal function and nutritional risk.')],
 'Begin nutrition when the perfusion context is safe','**Enteral nutrition is generally preferred when feasible after stabilization.**',['Do not confuse early feeding with immediate full-dose feeding.','Monitor abdominal findings, tolerance and the hemodynamic trajectory.'], '**Individualize progression and protein/energy targets.**',['Review aspiration risk and feeding access.','Reassess if shock or abdominal signs worsen.'],[['Stable gut/perfusion','Enteral route when feasible'],['Initial dose','Often gradual'],['Instability','Reassess safety']],[NU],style='clinical_scenario')

q('A severely malnourished patient develops profound hypophosphatemia, weakness and cardiac dysfunction shortly after nutrition is rapidly increased. Which syndrome is most likely?', 'Refeeding syndrome',[
 ('Starvation ketosis without electrolyte shifts','The deterioration after carbohydrate/nutrition introduction with phosphate loss suggests refeeding physiology.'),('Isolated hypervitaminosis D','This does not explain the characteristic timing and phosphate redistribution.'),('Primary myasthenia gravis','This does not explain the nutritional trigger and systemic electrolyte syndrome.')],
 'Insulin-driven shifts can destabilize a depleted patient','**Refeeding can lower phosphate, potassium and magnesium and expose thiamine deficiency.**',['Fluid and sodium retention can add cardiac/respiratory harm.','The biochemical pattern and clinical severity guide management.'], '**Slow or adjust nutrition and replace deficits with close monitoring.**',['Give thiamine according to the risk-based plan.','Assess cardiac rhythm, respiratory strength and fluid balance.'],[['Trigger','Rapid reintroduction of nutrition'],['Key shifts','Phosphate, potassium, magnesium'],['Prevention','Risk assessment and controlled advancement']],[NU,ref('ASPEN refeeding syndrome consensus','https://doi.org/10.1002/ncp.10474')],style='clinical_scenario')

q('A ventilated patient receives calories well above estimated needs and develops increasing CO2 production. Which mechanism can contribute?', 'Overfeeding, particularly excess carbohydrate delivery',[
 ('A guaranteed reduction in ventilatory demand from unlimited calories','Overfeeding can increase metabolic CO2 load.'),('A direct proof that all respiratory deterioration is new pneumonia','Infection is a differential, not a conclusion from increased CO2 alone.'),('Elimination of all dead-space ventilation by nutrition','Nutrition does not abolish physiological dead space.')],
 'More calories are not always better during critical illness','**Excess energy can increase CO2 production and metabolic complications.**',['Count non-nutritional calories such as propofol when relevant.','Measured or carefully estimated needs and the clinical phase guide delivery.'], '**Review total intake before simply increasing ventilator exposure.**',['Assess glucose, triglycerides and the respiratory trajectory.','Avoid both prolonged undernutrition and indiscriminate overfeeding.'],[['Excess energy','Can increase CO2'],['Hidden calories','Medication/lipid sources'],['Target','Phase- and patient-appropriate']],[NU],style='clinical_scenario')

q('When should supplemental or exclusive parenteral nutrition be considered in critical illness?', 'When enteral/oral intake is not feasible or remains insufficient, with timing individualized to nutritional risk and the clinical course',[
 ('Immediately at full dose in every ICU patient regardless of intake','This ignores enteral feasibility and overfeeding risk.'),('Never, even with a nonfunctional gut and severe nutritional need','PN has an important selected role.'),('Only after a fixed month of starvation in every patient','Timing should not ignore pre-existing malnutrition and anticipated course.')],
 'Route and timing are clinical decisions rather than universal calendar rules','**Nutrition risk, gut function and actual delivered intake determine the need for PN.**',['PN introduces line, metabolic and overfeeding risks.','Enteral intolerance should be investigated and managed rather than assumed permanent.'], '**Use a measured prescription and monitoring plan.**',['Assess electrolytes, glucose, triglycerides and refeeding risk.','Reassess the route as recovery proceeds.'],[['Enteral feasible','Usually preferred'],['Inadequate/not feasible','PN may be needed'],['Timing','Individual risk and course']],[NU])

q('A hemodynamically stable nonbleeding ICU adult has hemoglobin 6.6 g/dL, without acute MI, severe ischemia or another special indication. Which strategy generally fits current restrictive transfusion guidance?', 'Consider red-cell transfusion around a 7 g/dL threshold while assessing the whole clinical context',[
 ('Transfuse routinely whenever Hb is below 10 g/dL in every ICU patient','This is not the usual stable-patient restrictive approach.'),('Never transfuse unless Hb falls below 4 g/dL','This is not an appropriate universal threshold.'),('Use oxygen saturation alone to decide because hemoglobin does not affect content','Saturation can be normal despite reduced oxygen-carrying capacity.')],
 'Use a threshold within a syndrome-specific decision','**Restrictive transfusion is appropriate for many stable hospitalized/ICU adults.**',['Active bleeding, acute MI and other special circumstances require separate assessment.','Symptoms, ischemia and trajectory matter as well as the number.'], '**Transfuse to a clinical goal and reassess.**',['Balance oxygen-delivery benefit against circulatory overload and other transfusion harms.','Do not treat this threshold as a major-hemorrhage rule.'],[['Stable no special indication','Often about 7 g/dL'],['Active hemorrhage/ischemia','Different framework'],['Reassessment','After treatment']],[ref('AABB international RBC transfusion guideline: 2023','https://doi.org/10.1001/jama.2023.12914')],style='clinical_scenario')

q('A septic patient has falling platelets, prolonged PT, high D-dimer and falling fibrinogen with bleeding and microvascular organ injury. Which syndrome is most consistent?', 'Disseminated intravascular coagulation',[
 ('Immune TTP as established by prolonged PT alone','TTP has a different mechanism and often relatively preserved routine coagulation times.'),('Isolated immune thrombocytopenia','This does not explain the broad coagulation activation/consumption pattern.'),('Simple hemodilution as the only possible diagnosis','Dilution can contribute, but the septic consumptive pattern raises DIC.')],
 'Recognize systemic coagulation activation and consumption','**DIC can produce both thrombosis and bleeding.**',['Serial changes and the underlying cause matter.','Fibrinogen can initially be normal or high during inflammation, so a falling trend is informative.'], '**Treat the trigger and support clinically important hemostatic deficits.**',['Use blood components according to bleeding/procedural needs rather than every abnormal number alone.','Reassess for TMA and other mechanisms when the pattern is atypical.'],[['Platelets/PT','Consumption/coagulation clues'],['D-dimer','Fibrin turnover'],['Management','Cause treatment plus targeted support']],[ref('ISTH harmonized DIC diagnosis and treatment guidance','https://www.jthjournal.org/article/S1538-7836(22)13716-5/fulltext')],style='clinical_scenario')

q('Platelets fall by more than 50% on day 7 of heparin therapy and a new proximal DVT appears. The clinical 4Ts probability is high. What is the appropriate immediate principle?', 'Stop all heparin exposure and start a suitable non-heparin anticoagulant while confirmatory testing proceeds',[
 ('Continue heparin until the functional assay returns','High-probability suspected HIT carries substantial thrombotic risk.'),('Stop anticoagulation entirely despite new thrombosis without another contraindication','HIT is a prothrombotic syndrome that generally needs alternative anticoagulation.'),('Start warfarin alone immediately before platelet recovery','Early warfarin without appropriate management can cause severe complications.')],
 'Treat a high-probability prothrombotic drug reaction promptly','**HIT can cause thrombosis despite thrombocytopenia.**',['Use an immunoassay and selected functional testing according to the pathway.','Low-probability 4Ts cases should not be managed identically.'], '**Choose an alternative by organ function, bleeding risk and clinical stability.**',['Review flushes and circuit heparin as well as the main prescription.','Reassess if testing is negative or another cause emerges.'],[['High 4Ts plus thrombosis','Immediate action'],['Heparin','Stop all relevant exposure'],['Alternative','Non-heparin anticoagulant']],[ref('ASH HIT clinical practice guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC6258919/')],style='clinical_scenario')

q('A bleeding patient has marked fibrinogen depletion. Which component most directly replaces fibrinogen when indicated?', 'Cryoprecipitate or fibrinogen concentrate according to the local protocol',[
 ('Packed red cells alone','These restore red-cell mass but do not adequately replace fibrinogen.'),('Platelets alone','These address platelet deficits, not isolated fibrinogen replacement.'),('Albumin alone','This does not provide the needed coagulation substrate.')],
 'Match the component to the deficit','**Fibrinogen is a substrate for clot formation and can become critically depleted.**',['The required target and dose depend on the bleeding context and testing.','Major hemorrhage requires coordinated management of several deficits.'], '**Use clinical bleeding and protocol-guided reassessment.**',['Check temperature, calcium, platelets and other coagulation factors.','Do not correct one laboratory value while ongoing bleeding remains uncontrolled.'],[['RBC','Oxygen-carrying capacity'],['Platelets','Platelet contribution'],['Cryo/concentrate','Fibrinogen replacement']],[ref('European major bleeding guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC9977110/')])

q('A critically ill patient has high VTE risk but active major bleeding makes pharmacological prophylaxis unsafe. Which option is reasonable when not contraindicated?', 'Mechanical prophylaxis such as intermittent pneumatic compression with regular reassessment',[
 ('Full-dose anticoagulation regardless of bleeding','This can worsen immediate harm.'),('No preventive assessment for the remainder of admission','Risk and contraindications change over time.'),('An IVC filter routinely for every prophylaxis contraindication','Routine filter placement is not an equivalent standard preventive strategy.')],
 'A temporary bleeding contraindication needs a changing prevention plan','**Mechanical measures can be used while pharmacological prophylaxis is unsafe.**',['Skin, vascular and device safety must be considered.','When bleeding risk improves, reassess whether pharmacological prophylaxis can begin.'], '**Review both risks daily.**',['Mobilization where safe is complementary rather than a complete replacement.','Do not confuse prophylaxis with treatment of an established VTE.'],[['Bleeding active','Pharmacological caution'],['Mechanical option','Selected interim prevention'],['Reassessment','Risk changes with recovery']],[ref('ASH hospitalized medical patient VTE prevention guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC6258910/')],style='clinical_scenario')

q('Which ICU patient has a recognized stress-related upper-GI bleeding risk factor supporting prophylaxis consideration?', 'A patient with shock and coagulopathy',[
 ('A stable low-risk patient solely because of a brief ICU observation','Location alone does not establish sufficient risk.'),('Every enterally fed patient regardless of risk','Feeding does not create a universal indication.'),('Every recovered patient at hospital discharge','A resolved ICU risk does not justify automatic continuation.')],
 'Use risk-based stress-ulcer prevention','**SCCM/ASHP identifies shock, coagulopathy and chronic liver disease as important risk factors.**',['PPIs or H2 blockers can be selected according to the clinical context.','The prescription is preventive, not a substitute for diagnosing active GI bleeding.'], '**Document the indication and stopping plan.**',['Review adverse effects and other medication needs.','Reassess when risk factors resolve or the patient leaves the ICU.'],[['High-risk features','Support prophylaxis'],['Low risk','Avoid automatic prescription'],['Active bleeding','Requires a different treatment pathway']],[SU])

q('A patient’s shock and coagulopathy have resolved and there is no other acid-suppression indication. What should happen to ICU stress-ulcer prophylaxis?', 'Discontinue it when the risk indication is no longer present',[
 ('Continue indefinitely because it was started in the ICU','This perpetuates unnecessary medication exposure.'),('Continue until a serum gastrin target is reached','That is not the stopping framework.'),('Increase the dose routinely at ward transfer','Recovery does not itself justify escalation.')],
 'Prevent a temporary ICU order becoming a permanent prescription','**Stress-ulcer prophylaxis should stop when the relevant risk resolves.**',['A separate indication such as established acid disease or another GI risk can change the plan.','Medication reconciliation should identify the original reason.'], '**Review at transfer and discharge.**',['Explain continuation only when it remains justified.','Do not stop a drug needed for another established indication without checking.'],[['Risk resolved','Stop prophylaxis'],['Other indication','Assess separately'],['Transitions','Medication reconciliation']],[SU])

q('An ICU patient is quiet and withdrawn but fluctuates in attention and cannot follow a simple cognitive task despite adequate arousal. Which syndrome should be assessed?', 'Hypoactive delirium',[
 ('Absence of delirium because there is no agitation','Delirium can be hypoactive.'),('Permanent dementia as established from the ICU examination alone','Acute fluctuation in critical illness requires delirium and other cause assessment.'),('Deep coma despite sufficient arousal for testing','Coma and assessable delirium are different states.')],
 'Delirium is not synonymous with agitation','**Inattention with acute fluctuation is central to delirium assessment.**',['Use a validated ICU tool when arousal permits.','Drugs, infection, metabolic disturbance, sleep disruption and organ dysfunction can contribute.'], '**Treat causes and use a multicomponent prevention/support strategy.**',['Reorient, support sleep, review sensory aids and mobilize when safe.','Routine antipsychotic treatment does not reliably solve the underlying syndrome.'],[['Hypoactive','Can be easily missed'],['Assessment','Requires adequate arousal'],['Management','Cause correction and supportive measures']],[PA],style='clinical_scenario')

q('What is the appropriate approach to mobilization during critical illness?', 'An individualized progressive program with physiological and device-safety screening',[
 ('Maximal-intensity mobilization for every unstable patient','Intensity must reflect safety and tolerance.'),('Permanent bed rest until all organ support is removed','This can prolong deconditioning in patients who could safely mobilize.'),('Assume early aggressive mobilization has proven benefit without adverse events in every trial','Trials show important limits and safety trade-offs.')],
 'Early does not mean indiscriminately intense','**Mobilization can be valuable but must be matched to clinical stability.**',['Assess cardiovascular, respiratory, neurological and line/device constraints.','The activity level can change from day to day.'], '**Coordinate a multidisciplinary plan.**',['Stop or adjust for intolerance.','Set functional goals rather than a fixed intensity irrespective of the patient.'],[['Safety screen','Before activity'],['Progression','Individualized'],['Outcome','Function and participation']],[PA,ref('TEAM randomized early-mobilization trial','https://doi.org/10.1056/NEJMoa2209083')])

q('A survivor of prolonged critical illness has weakness, memory difficulty, anxiety and reduced work capacity after discharge. Which concept best unifies the assessment needs?', 'Post-intensive care syndrome',[
 ('A guarantee that recurrent infection explains every symptom','Infection may need evaluation but does not account for all common recovery domains.'),('Proof that discharge physiology excludes ongoing disability','Survival and hospital discharge do not imply full recovery.'),('A single psychiatric diagnosis that makes physical rehabilitation unnecessary','Physical, cognitive and psychological problems can coexist.')],
 'Recovery extends beyond resolution of the acute organ failure','**PICS includes new or worsened physical, cognitive and mental-health impairment after critical illness.**',['Family members may also have substantial psychological burden.','Symptoms need assessment for treatable alternative causes.'], '**Arrange individualized rehabilitation and follow-up.**',['Review medications, nutrition, sleep, cognition and functional goals.','Communicate expected recovery needs and warning symptoms clearly.'],[['Physical','Weakness and deconditioning'],['Cognitive','Attention/memory problems'],['Psychological','Anxiety, depression or trauma symptoms']],[ref('Surviving Sepsis Campaign recovery recommendations: 2026','https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026')],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',3,'Critical-care Emergencies and Organ Support','critical-organ-support',rows,40)
